import { Component, EventEmitter, Input, Output, forwardRef, inject, input } from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR, FormsModule } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { Question } from '../../models/ui/question.model';
import { CopyPasteDirective } from '../../directives/copy-paste.directive'
import { QaService } from '../../services/qa/qa.service';

@Component({
  selector: 'app-multi-input',
  standalone: true,
  imports: [CommonModule, FormsModule, CopyPasteDirective],
  templateUrl: `./multi-input.component.html`,
  styleUrls: ['./multi-input.component.css'],
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => MultiInputComponent),
      multi: true
    }
  ]
})
export class MultiInputComponent implements ControlValueAccessor {
  qaService = inject(QaService);
  @Input() label: string = '';
  @Input() type: string = 'text';
  question = input<Question | null>(null);
  
  @Output() valuesChange = new EventEmitter<any[]>();

  values: any[] = [''];  // Initialize with an empty string

  onValueChange(index: number, newValue: any) {
    this.onChange(this.values);
  }

  onInputBlur() {
    this.onTouched();
    this.valuesChange.emit(this.values);
    this.ensureMinimumInputs();
  }

  addValue() {
    this.values.push('');
    this.onChange(this.values);
    this.valuesChange.emit(this.values);
  }
  
  removeValue(index: number) {
    this.values.splice(index, 1);
    this.ensureMinimumInputs();
    this.onChange(this.values);
    this.valuesChange.emit(this.values);
  }

  writeValue(value: any[]): void {
    if (Array.isArray(value) && value.length > 0) {
      this.values = [...value];
    } else {
      this.values = [''];  // Initialize with an empty string if no values
    }
    this.ensureMinimumInputs();
  }

  ensureMinimumInputs(): void {
    if (this.values.length === 0) {
      this.values.push('');
    }
  }

  onChange: (value: any) => void = () => {};
  onTouched: () => void = () => {};

  registerOnChange(fn: any): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: any): void {
    this.onTouched = fn;
  }

  onQaClick(): void {
    const q = this.question();
    if (q) this.qaService.openDialog(q);
  }
}